import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
const origin=process.argv[2],label=process.argv[3];
const prefix=process.argv[4]??'core-group1';
if(!/^[a-z0-9-]{3,80}$/.test(prefix))throw new Error('Safe evidence prefix required');
const host=new URL(origin);
if(host.protocol!=='https:'||host.pathname!=='/'||host.search||host.hash||host.username||!['PREVIEW','PROD'].includes(label))throw new Error('Explicit owned hosted origin and evidence label required');
if(label==='PROD'&&origin!=='https://app.reconiq.example')throw new Error('Canonical PROD origin required');
if(label==='PREVIEW'&&!host.hostname.endsWith('.fvi-app.pages.dev'))throw new Error('Owned fvi-app preview required');
const root='./LOCAL_USER/AppData/Local/Temp/fvi-codex-docs-release-20260930';
const sha=value=>createHash('sha256').update(value).digest('hex');
const response=await fetch(origin+'/auth?core-group1=20261004',{redirect:'error',cache:'no-store',signal:AbortSignal.timeout(25000)});
const html=await response.text();
if(response.status!==200||response.headers.get('X-FVI-CSP-Nonce-Applied')!=='1')throw new Error('Hosted sign-in/CSP readback unconfirmed');
const asset=html.match(/(?:href|src)=["']([^"']*\/assets\/styles-[^"']+\.css)["']/)?.[1];
if(!asset)throw new Error('Actual hosted stylesheet missing');
const assetPath=new URL(asset,origin).pathname;
if(!/^\/assets\/styles-[A-Za-z0-9_-]+\.css$/.test(assetPath))throw new Error('Unexpected stylesheet path');
const local=await readFile(path.join(root,'dist',assetPath));
const css=await fetch(origin+assetPath,{redirect:'error',cache:'no-store',signal:AbortSignal.timeout(25000)});
const bytes=Buffer.from(await css.arrayBuffer());
if(!css.ok||sha(bytes)!==sha(local))throw new Error('Hosted reviewed stylesheet differs');
const invitation=await fetch(origin+'/request-invite?core-group1=20261004',{redirect:'error',cache:'no-store',signal:AbortSignal.timeout(25000)});
if(invitation.status!==200||invitation.headers.get('X-FVI-CSP-Nonce-Applied')!=='1')throw new Error('Hosted registration entry unconfirmed');
await invitation.body?.cancel();
const receipt={at:new Date().toISOString(),label,origin,authStatus:response.status,invitationEntryStatus:invitation.status,cspNonceApplied:'1',stylesheet:assetPath,localSha256:sha(local),hostedSha256:sha(bytes),exact:true,authenticatedWorkflowAcceptance:false,emailSent:false};
const file=path.join(root,'audit',`${prefix}-${label.toLowerCase()}-readback-20261004.json`);
await writeFile(file,JSON.stringify(receipt,null,2),{flag:'wx'});
console.log(JSON.stringify(receipt));
